package com.aicharacter.v3;
/** Physical cat work raises oxygen/energy demand; debt and fatigue then reduce achievable movement. */
public final class CatCardioMetabolicEngine{private CatCardioMetabolicEngine(){}
 public static void advance(WorldState s,double dt,long now){if(s==null||dt<=0||s.catState==null)return;if(s.catMetabolism==null)s.catMetabolism=new CatMetabolismState();if(s.catRespiration==null)s.catRespiration=new CatRespirationState();CatMetabolismState m=s.catMetabolism;CatRespirationState r=s.catRespiration;PhysicsBodyState p=s.catPhysics;double speed=s.catTravel!=null&&s.catTravel.active?Math.max(0,s.catTravel.lastSpeed):0,work=cl(speed/125.0),slip=p==null?0:p.slipSeverity,recovery=s.catNervous==null?0:s.catNervous.recoveryDrive;double demand=cl(.12+work*.68+slip*.12+recovery*.10);m.demand=follow(m.demand,demand,dt,1.7);double atmospheric=s.atmosphere==null?1:cl((s.atmosphere.oxygenFraction/.2095)*(s.atmosphere.pressureKpa/101.325));r.breathingDrive=follow(r.breathingDrive,cl(.08+m.demand*.82+m.oxygenDebt*.35),dt,.8);double ventilation=cl(.62+r.breathingDrive*.46);r.oxygenDelivery=cl(atmospheric*ventilation*(1-r.strain*.35));double shortage=Math.max(0,m.demand-r.oxygenDelivery);m.oxygenDebt=cl(m.oxygenDebt+(shortage*.13-m.oxygenDebt*(work<.08?.055:.018))*dt);double workAboveRest=Math.max(0,m.demand-.14),reserveCostPerSecond=workAboveRest*(2.15/3600.0);s.catState.energy=Math.max(0,s.catState.energy-reserveCostPerSecond*dt);if(s.catState.awake)s.catState.sleepiness=Math.min(100,s.catState.sleepiness+dt*(work*.55/3600.0));m.availableEnergy=cl((s.catState.energy/100.0)*(1-m.oxygenDebt*.62));m.fatigue=cl(m.fatigue+(m.demand*.016+shortage*.09-(work<.08?.032:.006))*dt);m.metabolicHeat=cl(.08+m.demand*.76);r.strain=follow(r.strain,cl(shortage*.9+m.oxygenDebt*.42),dt,1.2);r.lastUpdatedAt=Math.max(r.lastUpdatedAt,now);}
 public static double locomotorCapacity(WorldState s){if(s==null||s.catMetabolism==null)return 1;CatMetabolismState m=s.catMetabolism;double sleepy=s.catState==null?0:cl(s.catState.sleepiness/100.0);return Math.max(.28,(.38+.62*m.availableEnergy)*(1-m.fatigue*.48)*(1-m.oxygenDebt*.38)*(1-sleepy*.22));}
 private static double follow(double v,double t,double dt,double tau){double k=1-Math.exp(-Math.min(dt,60)/Math.max(.05,tau));return cl(v+(t-v)*k);}private static double cl(double v){return Math.max(0,Math.min(1,v));}
}